import json, subprocess, random, itertools, os, sys

RELAY = "/home/c/brix2/b/task081/relay.py"
TMP = "/tmp/nrt/fuzz.json"

def dijkstra(nodes, edges, src, dst):
    # edges: dict (u,v)->cost considered usable
    INF = float("inf")
    dist = {n: None for n in nodes}
    dist[src] = 0
    best = {n: None for n in nodes}
    best[src] = [src]
    done = set()
    while True:
        u = None
        for n in nodes:
            if n in done or dist[n] is None:
                continue
            if u is None or (dist[n], best[n]) < (dist[u], best[u]):
                u = n
        if u is None:
            break
        done.add(u)
        for (a, b), w in edges.items():
            if a != u or b in done:
                continue
            nd = dist[u] + w
            np = best[u] + [b]
            if dist[b] is None or (nd, np) < (dist[b], best[b]):
                dist[b], best[b] = nd, np
    return (dist[dst], best[dst]) if best[dst] is not None else (None, None)

def reference(nodes, links, S, D, W, items):
    up_links = {(l["from"], l["to"]): l["cost"] for l in links if l["up"]}
    pc, pp = dijkstra(nodes, up_links, S, D)
    if pp is None:
        return 5, None
    primary = (pc, pp)
    prefix_dist, _ = dijkstra(nodes, up_links, S, D)  # need dist from S
    # recompute full distance map from S
    def dmap(src):
        dist = {n: None for n in nodes}; dist[src] = 0
        best = {n: None for n in nodes}; best[src] = [src]; done=set()
        while True:
            u=None
            for n in nodes:
                if n in done or dist[n] is None: continue
                if u is None or (dist[n],best[n])<(dist[u],best[u]): u=n
            if u is None: break
            done.add(u)
            for (a,b),w in up_links.items():
                if a!=u or b in done: continue
                nd=dist[u]+w; np=best[u]+[b]
                if dist[b] is None or (nd,np)<(dist[b],best[b]):
                    dist[b],best[b]=nd,np
        return dist,best
    sdist,_ = dmap(S)
    repairs=[]
    for k in range(len(pp)-2):
        u=pp[k]; v=pp[k+1]
        deleted=set(pp[:k])|{v}
        rn=[n for n in nodes if n not in deleted]
        re_={e:w for e,w in up_links.items() if e[0] not in deleted and e[1] not in deleted}
        sc,sp=dijkstra(rn,re_,u,D)
        if sp is None: return 5,None
        repairs.append((sdist[u]+sc, pp[:k+1]+sp[1:]))
    up={n:True for n in nodes}
    def usable(route):
        return all(up[n] for n in route[1])
    def target():
        if usable(primary): return primary
        cand=[r for r in repairs if usable(r)]
        if not cand: return None
        return min(cand)
    installed=primary; tstart=None; tat=None; ttgt=None
    events=[]; completed=0; i=0; n=len(items)
    while i<n or tat is not None:
        wakes=[]
        if i<n: wakes.append(items[i][0])
        if tat is not None: wakes.append(tat)
        now=min(wakes)
        while i<n and items[i][0]==now:
            _,node,z=items[i]; i+=1
            old=[installed[0],installed[1]]
            real=0
            if up[node]!=z:
                up[node]=z; real=1
            nt=target()
            if real:
                if nt is None: return 5,None
                if nt!=installed:
                    tstart=now; tat=now+W
                    if tat>9223372036854775807: return 5,None
                    ttgt=nt
                else:
                    tstart=tat=ttgt=None
            due=tat
            tgt = [ttgt[0],ttgt[1]] if tat is not None else [installed[0],installed[1]]
            events.append([now,0,node,z,real,old,tgt,due])
        if tat is not None and tat==now:
            oi=installed; installed=ttgt
            events.append([now,1,[oi[0],oi[1]],[installed[0],installed[1]],now-tstart])
            completed+=1; tstart=tat=ttgt=None
    out={"s":S,"d":D,"m":[primary[0],primary[1]],
         "b":[[pp[k+1],[repairs[k][0],repairs[k][1]]] for k in range(len(repairs))],
         "e":events,"r":completed,"f":[installed[0],installed[1]]}
    return 0,out

def run_case(nodes, links, S, D, W, items):
    topo={"nodes":nodes,"links":links}
    with open(TMP,"w") as f: json.dump(topo,f)
    data=json.dumps(items)
    p=subprocess.run([sys.executable,RELAY,"nrepair",TMP,S,D,str(W),data],
                     capture_output=True)
    return p

