trials=0
for trial in range(4000):
    V=random.randint(2,6)
    nodes=[chr(65+i) for i in range(V)]
    S,D="A",chr(64+V)
    edges=[]
    for a,b in itertools.permutations(nodes,2):
        if random.random()<0.35:
            edges.append({"from":a,"to":b,"cost":random.randint(1,6),
                          "up":random.random()<0.85,
                          "bandwidth":1,"latency":0})
    W=random.randint(0,5)
    m=random.randint(0,8)
    t=0; items=[]
    for _ in range(m):
        t+=random.randint(0,2)
        items.append([t,random.choice(nodes),random.random()<0.5])
    p=run_case(nodes,edges,S,D,W,items)
    rc,ref=reference(nodes,edges,S,D,W,items)
    if p.returncode!=rc:
        print("CODE MISMATCH",p.returncode,rc)
        print(json.dumps({"nodes":nodes,"links":edges}))
        print(items,"W=",W); print(p.stderr.decode()); break
    if rc==0:
        got=json.loads(p.stdout.decode())
        if got!=ref:
            print("OUTPUT MISMATCH")
            print(json.dumps({"nodes":nodes,"links":edges}))
            print("items",items,"W",W)
            print("got ",json.dumps(got))
            print("ref ",json.dumps(ref))
            break
    trials+=1
else:
    print("ALL OK",trials)

